# PY-459..PY-500: Object-Oriented Programming (continued): more abstraction (7), polymorphism (20), class/static methods and composition (15).

# ---- 7 abstraction, bespoke ----
py(O, "Abstract Shape Report", "An abstract `Shape` declares `area()` and `perimeter()`. `Rect(l, w)` and `Square(s)` implement them. Each line `rect l w` or `square s`; print `area perimeter`.", "First line `n`, then `n` lines.", "One line per shape.", "1 <= n <= 20",
   "from abc import ABC, abstractmethod\n\n\nclass Shape(ABC):\n    @abstractmethod\n    def area(self):\n        ...\n\n    @abstractmethod\n    def perimeter(self):\n        ...\n\n\nclass Rect(Shape):\n    def __init__(self, l, w):\n        self.l, self.w = l, w\n\n    def area(self):\n        return self.l * self.w\n\n    def perimeter(self):\n        return 2 * (self.l + self.w)\n\n\nclass Square(Rect):\n    def __init__(self, s):\n        super().__init__(s, s)\n\n\nn = int(input())\nfor _ in range(n):\n    p = input().split()\n    s = Rect(int(p[1]), int(p[2])) if p[0] == \"rect\" else Square(int(p[1]))\n    print(s.area(), s.perimeter())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: r.choice([f"rect {r.randint(1, 30)} {r.randint(1, 30)}", f"square {r.randint(1, 30)}"])), edges=["1\nsquare 1\n"])
py(O, "Cannot Instantiate Abstract", "`Document` is abstract with an abstract method `render()`; `Pdf` and `Html` implement it. For each class name print `created` if an object could be created and `TypeError` if Python refuses.", "First line `n`, then `n` names from `Document`, `Pdf`, `Html`.", "One line per name.", "1 <= n <= 10",
   "from abc import ABC, abstractmethod\n\n\nclass Document(ABC):\n    @abstractmethod\n    def render(self):\n        ...\n\n\nclass Pdf(Document):\n    def render(self):\n        return \"pdf\"\n\n\nclass Html(Document):\n    def render(self):\n        return \"html\"\n\n\nk = {\"Document\": Document, \"Pdf\": Pdf, \"Html\": Html}\nn = int(input())\nfor _ in range(n):\n    try:\n        k[input().strip()]()\n        print(\"created\")\n    except TypeError:\n        print(\"TypeError\")", lambda r: cmd_block(r, r.randint(2, 6), lambda r: r.choice(["Document", "Pdf", "Html"])), edges=["1\nDocument\n"])
py(O, "Template Method Report", "An abstract `Report` fixes the steps `header`, `body` and `footer` in `build()`: it prints `== <title> ==`, then the abstract body, then `-- end --`. `SalesReport` prints `total sales: <n>` and `StaffReport` prints `staff count: <n>`. Each line `kind title n`.", "First line `n`, then `n` lines `kind title value`.", "Three lines per report.", "1 <= n <= 10",
   "from abc import ABC, abstractmethod\n\n\nclass Report(ABC):\n    def __init__(self, title, value):\n        self.title, self.value = title, value\n\n    def build(self):\n        print(f\"== {self.title} ==\")\n        print(self.body())\n        print(\"-- end --\")\n\n    @abstractmethod\n    def body(self):\n        ...\n\n\nclass SalesReport(Report):\n    def body(self):\n        return f\"total sales: {self.value}\"\n\n\nclass StaffReport(Report):\n    def body(self):\n        return f\"staff count: {self.value}\"\n\n\nk = {\"sales\": SalesReport, \"staff\": StaffReport}\nn = int(input())\nfor _ in range(n):\n    a, t, v = input().split()\n    k[a](t, int(v)).build()", lambda r: cmd_block(r, r.randint(1, 3), lambda r: f"{r.choice(['sales', 'staff'])} {r.choice(['Q1', 'May', 'North'])} {r.randint(1, 900)}"), edges=["1\nsales A 1\n"])
py(O, "Employee Net Salary Abstraction", "An abstract `Employee` has an abstract `gross()` and a concrete `net()` which subtracts 10% tax (rounded down) from the gross. `Fixed` pays `base`; `Hourly` pays `rate * hours`. Each line `fixed base` or `hourly rate hours`; print the net salary.", "First line `n`, then `n` lines.", "One net salary per line.", "1 <= n <= 20",
   "from abc import ABC, abstractmethod\n\n\nclass Employee(ABC):\n    @abstractmethod\n    def gross(self):\n        ...\n\n    def net(self):\n        g = self.gross()\n        return g - g // 10\n\n\nclass Fixed(Employee):\n    def __init__(self, base):\n        self.base = base\n\n    def gross(self):\n        return self.base\n\n\nclass Hourly(Employee):\n    def __init__(self, rate, hours):\n        self.rate, self.hours = rate, hours\n\n    def gross(self):\n        return self.rate * self.hours\n\n\nn = int(input())\nfor _ in range(n):\n    p = input().split()\n    e = Fixed(int(p[1])) if p[0] == \"fixed\" else Hourly(int(p[1]), int(p[2]))\n    print(e.net())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: r.choice([f"fixed {r.randint(10, 90) * 1000}", f"hourly {r.randint(100, 400)} {r.randint(10, 200)}"])), edges=["1\nfixed 10\n"])
py(O, "Plugin Runner Interface", "Every plugin implements an abstract `run(text)`. `Upper` upper-cases, `Reverse` reverses and `Trim` removes surrounding spaces. Read the plugin names to run in order, then the text; print the final text.", "Line 1: plugin names; line 2: the text.", "The transformed text.", "Names are `Upper`, `Reverse` or `Trim`.",
   "from abc import ABC, abstractmethod\n\n\nclass Plugin(ABC):\n    @abstractmethod\n    def run(self, t):\n        ...\n\n\nclass Upper(Plugin):\n    def run(self, t):\n        return t.upper()\n\n\nclass Reverse(Plugin):\n    def run(self, t):\n        return t[::-1]\n\n\nclass Trim(Plugin):\n    def run(self, t):\n        return t.strip()\n\n\nk = {\"Upper\": Upper, \"Reverse\": Reverse, \"Trim\": Trim}\nnames = input().split()\ntext = input()\nfor nm in names:\n    text = k[nm]().run(text)\nprint(text)", lambda r: rows(" ".join(r.choice(["Upper", "Reverse", "Trim"]) for _ in range(r.randint(1, 4))), r.choice(["  Hello World ", "abc", " Py ", "x y"])), edges=["Trim\n  a \n"])
py(O, "Abstract Property Contract", "An abstract class `Appliance` requires every subclass to define the property `watts`. `Fan` is 60 W, `Heater` is 1500 W and `Lamp` is 10 W. For each `kind hours` print the energy in watt-hours.", "First line `n`, then `n` lines `kind hours`.", "One number per line.", "1 <= n <= 20",
   "from abc import ABC, abstractmethod\n\n\nclass Appliance(ABC):\n    @property\n    @abstractmethod\n    def watts(self):\n        ...\n\n    def energy(self, hours):\n        return self.watts * hours\n\n\nclass Fan(Appliance):\n    watts = 60\n\n\nclass Heater(Appliance):\n    watts = 1500\n\n\nclass Lamp(Appliance):\n    watts = 10\n\n\nk = {\"fan\": Fan, \"heater\": Heater, \"lamp\": Lamp}\nn = int(input())\nfor _ in range(n):\n    a, h = input().split()\n    print(k[a]().energy(int(h)))", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(['fan', 'heater', 'lamp'])} {r.randint(1, 24)}"), edges=["1\nlamp 1\n"])
py(O, "Abstract Storage Backends", "An abstract `Storage` declares `save(key, value)` and `load(key)`. `MemoryStorage` keeps values in a dictionary; `LoggingStorage` does the same and also counts saves. Commands: `save k v`, `load k`, `saves` (for the logging one only). Use `LoggingStorage` and print `load` results (or `missing`) and the save count.", "First line `n`, then `n` commands.", "One line per `load` and `saves`.", "1 <= n <= 30",
   "from abc import ABC, abstractmethod\n\n\nclass Storage(ABC):\n    @abstractmethod\n    def save(self, k, v):\n        ...\n\n    @abstractmethod\n    def load(self, k):\n        ...\n\n\nclass MemoryStorage(Storage):\n    def __init__(self):\n        self.d = {}\n\n    def save(self, k, v):\n        self.d[k] = v\n\n    def load(self, k):\n        return self.d.get(k, \"missing\")\n\n\nclass LoggingStorage(MemoryStorage):\n    def __init__(self):\n        super().__init__()\n        self.count = 0\n\n    def save(self, k, v):\n        self.count += 1\n        super().save(k, v)\n\n\ns = LoggingStorage()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"save\":\n        s.save(c[1], c[2])\n    elif c[0] == \"load\":\n        print(s.load(c[1]))\n    else:\n        print(s.count)", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"save {r.choice('abc')} {r.randint(1, 9)}", f"load {r.choice('abc')}", "saves"])), edges=["1\nsaves\n"])

# ---- 10 polymorphism with special methods ----
py(O, "Vector Addition Operator", "A `Vector` class overloads `+` so two vectors add component-wise, and `__str__` shows `(x, y)`. Each line `x1 y1 x2 y2`; print the sum.", "First line `n`, then `n` lines.", "One vector per line.", "1 <= n <= 20",
   "class Vector:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n\n    def __add__(self, o):\n        return Vector(self.x + o.x, self.y + o.y)\n\n    def __str__(self):\n        return f\"({self.x}, {self.y})\"\n\n\nn = int(input())\nfor _ in range(n):\n    a, b, c, d = map(int, input().split())\n    print(Vector(a, b) + Vector(c, d))", lambda r: cmd_block(r, r.randint(1, 5), lambda r: one_line(*[r.randint(-9, 9) for _ in range(4)]).strip()), edges=["1\n0 0 0 0\n"])
py(O, "Money Comparison Operators", "A `Money` class defines `==`, `<` and `+`. Given two amounts print `a+b`, then `a<b` as `True`/`False` and `a==b` as `True`/`False` on one line.", "First line `n`, then `n` lines `a b`.", "One line per pair: `sum less equal`.", "1 <= n <= 20",
   "class Money:\n    def __init__(self, v):\n        self.v = v\n\n    def __add__(self, o):\n        return Money(self.v + o.v)\n\n    def __lt__(self, o):\n        return self.v < o.v\n\n    def __eq__(self, o):\n        return self.v == o.v\n\n\nn = int(input())\nfor _ in range(n):\n    a, b = map(int, input().split())\n    A, B = Money(a), Money(b)\n    print((A + B).v, A < B, A == B)", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.randint(1, 5)} {r.randint(1, 5)}"), edges=["1\n3 3\n"])
py(O, "Sorting Custom Objects", "A `Card` class compares by `rank` using `__lt__` so Python's `sorted` can order a hand. Read `n` cards `name rank` and print the names from lowest to highest rank (ties keep input order).", "First line `n`, then `n` lines `name rank`.", "The sorted names.", "1 <= n <= 20",
   "class Card:\n    def __init__(self, name, rank):\n        self.name, self.rank = name, rank\n\n    def __lt__(self, o):\n        return self.rank < o.rank\n\n\nn = int(input())\ncards = []\nfor _ in range(n):\n    a, b = input().split()\n    cards.append(Card(a, int(b)))\nprint(*(c.name for c in sorted(cards)))", lambda r: cmd_block(r, r.randint(2, 7), lambda r: f"{r.choice('ABCDEFG')}{r.randint(1, 3)} {r.randint(1, 13)}"), edges=["1\nA 1\n"])
py(O, "Container Length and Index", "A `Playlist` class defines `__len__`, `__getitem__` and `__contains__`. After reading the songs print `len`, then the song at each queried index (or `no such song`), and whether `x in playlist`.", "Line 1: the songs; then `q`, then `q` queried indices; then a song name `x`.", "The length, `q` results and `True`/`False`.", "1 <= number of songs <= 20",
   "class Playlist:\n    def __init__(self, s):\n        self.s = s\n\n    def __len__(self):\n        return len(self.s)\n\n    def __getitem__(self, i):\n        return self.s[i]\n\n    def __contains__(self, x):\n        return x in self.s\n\n\np = Playlist(input().split())\nq = int(input())\nidx = list(map(int, input().split()))\nx = input().strip()\nprint(len(p))\nfor i in idx:\n    try:\n        print(p[i])\n    except IndexError:\n        print(\"no such song\")\nprint(x in p)", lambda r: (lambda s: rows(" ".join(s), 3, " ".join(str(r.randint(0, len(s))) for _ in range(3)), r.choice(s + ["zzz"])))(r.sample(["rock", "jazz", "pop", "folk", "blues", "soul"], r.randint(2, 5))), edges=["a\n1\n5\na\n"])
py(O, "Callable Discount Object", "A `Discount` object is called like a function: `Discount(p)(price)` returns the price after `p` percent off (rounded down). Read `p`, then prices, and print each discounted price.", "First line `p`, then `n`, then `n` prices.", "The discounted prices separated by spaces.", "0 <= p <= 100",
   "class Discount:\n    def __init__(self, p):\n        self.p = p\n\n    def __call__(self, price):\n        return price * (100 - self.p) // 100\n\n\nd = Discount(int(input()))\nn = int(input())\nprint(*(d(x) for x in map(int, input().split())))", lambda r: (lambda k: rows(r.randint(0, 60), k, " ".join(str(r.randint(10, 999)) for _ in range(k))))(r.randint(2, 6)), edges=["0\n1\n5\n"])
py(O, "Version Number Comparison", "A `Version` class parses `major.minor.patch` and supports `<`, `==` and `>` (using `functools.total_ordering`). For each pair of versions print `older`, `same` or `newer` for the first compared to the second.", "First line `n`, then `n` lines `v1 v2`.", "One word per line.", "Each version has three integers.",
   "from functools import total_ordering\n\n\n@total_ordering\nclass Version:\n    def __init__(self, s):\n        self.t = tuple(map(int, s.split(\".\")))\n\n    def __eq__(self, o):\n        return self.t == o.t\n\n    def __lt__(self, o):\n        return self.t < o.t\n\n\nn = int(input())\nfor _ in range(n):\n    a, b = map(Version, input().split())\n    print(\"older\" if a < b else \"same\" if a == b else \"newer\")", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.randint(0, 2)}.{r.randint(0, 3)}.{r.randint(0, 3)} {r.randint(0, 2)}.{r.randint(0, 3)}.{r.randint(0, 3)}"), edges=["1\n1.0.0 1.0.0\n"])
py(O, "Sum of Money With Radd", "A `Money` class supports `+` and also works with `sum()` (starting from 0) through `__radd__`. Print the total of `n` amounts as `Money(total)`.", "First line `n`, then `n` amounts.", "`Money(total)`.", "1 <= n <= 30",
   "class Money:\n    def __init__(self, v):\n        self.v = v\n\n    def __add__(self, o):\n        return Money(self.v + (o.v if isinstance(o, Money) else o))\n\n    __radd__ = __add__\n\n    def __repr__(self):\n        return f\"Money({self.v})\"\n\n\nn = int(input())\nprint(sum(Money(x) for x in map(int, input().split())))", lambda r: (lambda k: rows(k, " ".join(str(r.randint(1, 200)) for _ in range(k))))(r.randint(1, 8)), edges=["1\n5\n"])
py(O, "Matrix Product Operator", "A `Matrix2` class stores a 2 by 2 matrix and overloads `*` for matrix multiplication. Each test gives two matrices (four numbers per line); print the product as two lines.", "First line `n`, then `n` pairs of lines `a b c d` (a matrix is `[[a, b], [c, d]]`).", "Two lines per product.", "1 <= n <= 5",
   "class Matrix2:\n    def __init__(self, a, b, c, d):\n        self.m = [[a, b], [c, d]]\n\n    def __mul__(self, o):\n        x, y = self.m, o.m\n        return Matrix2(*(sum(x[i][k] * y[k][j] for k in range(2)) for i in range(2) for j in range(2)))\n\n    def show(self):\n        print(*self.m[0])\n        print(*self.m[1])\n\n\nn = int(input())\nfor _ in range(n):\n    a = Matrix2(*map(int, input().split()))\n    b = Matrix2(*map(int, input().split()))\n    (a * b).show()", lambda r: cmd_block(r, r.randint(1, 3), lambda r: one_line(*[r.randint(-3, 5) for _ in range(4)]).strip() + "\n" + one_line(*[r.randint(-3, 5) for _ in range(4)]).strip()), edges=["1\n1 0 0 1\n2 3 4 5\n"])
py(O, "Readable and Debug Text", "A `Book` class defines `__str__` (`<title> by <author>`) and `__repr__` (`Book('<title>')`). For each line `title author` print `str(book)` and then `repr(book)` on the next line.", "First line `n`, then `n` lines `title author`.", "Two lines per book.", "1 <= n <= 10",
   "class Book:\n    def __init__(self, t, a):\n        self.t, self.a = t, a\n\n    def __str__(self):\n        return f\"{self.t} by {self.a}\"\n\n    def __repr__(self):\n        return f\"Book({self.t!r})\"\n\n\nn = int(input())\nfor _ in range(n):\n    t, a = input().split()\n    b = Book(t, a)\n    print(str(b))\n    print(repr(b))", lambda r: cmd_block(r, r.randint(1, 4), lambda r: f"{r.choice(['Dune', 'Emma', 'Heidi', 'Ulysses'])} {r.choice(NM)}"), edges=["1\nA B\n"])
py(O, "Iterable Countdown Class", "A `Countdown(n)` class is iterable: it yields `n, n-1, ..., 1` through `__iter__` and `__next__`. Print the numbers separated by spaces, then the total of the numbers.", "One integer `n`.", "Two lines.", "0 <= n <= 100",
   "class Countdown:\n    def __init__(self, n):\n        self.n = n\n\n    def __iter__(self):\n        return self\n\n    def __next__(self):\n        if self.n <= 0:\n            raise StopIteration\n        v = self.n\n        self.n -= 1\n        return v\n\n\nvals = list(Countdown(int(input())))\nprint(*vals)\nprint(sum(vals))", lambda r: f"{r.randint(0, 20)}\n", edges=["0\n", "1\n"])

# ---- 10 polymorphism with overriding and duck typing ----
py(O, "Animal Sounds", "`Animal.speak()` is overridden by `Dog` (`Woof`), `Cat` (`Meow`) and `Cow` (`Moo`). Print `<name> says <sound>` for each line `kind name`.", "First line `n`, then `n` lines.", "One line per animal.", "1 <= n <= 20",
   "class Animal:\n    def __init__(self, name):\n        self.name = name\n\n    def speak(self):\n        return \"...\"\n\n    def line(self):\n        return f\"{self.name} says {self.speak()}\"\n\n\nclass Dog(Animal):\n    def speak(self):\n        return \"Woof\"\n\n\nclass Cat(Animal):\n    def speak(self):\n        return \"Meow\"\n\n\nclass Cow(Animal):\n    def speak(self):\n        return \"Moo\"\n\n\nk = {\"dog\": Dog, \"cat\": Cat, \"cow\": Cow, \"fish\": Animal}\nn = int(input())\nfor _ in range(n):\n    a, b = input().split()\n    print(k[a](b).line())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(['dog', 'cat', 'cow', 'fish'])} {r.choice(NM)}"), edges=["1\nfish A\n"])
py(O, "Total Area of Mixed Shapes", "A list holds `Circle`, `Rect` and `Tri` objects that all have an `area()` method. Read the shapes and print the total area with two decimals (use 3.14159 for pi, triangles use half base times height).", "First line `n`, then `n` lines: `circle r`, `rect l w` or `tri b h`.", "The total area.", "1 <= n <= 20",
   "class Circle:\n    def __init__(self, r):\n        self.r = r\n\n    def area(self):\n        return 3.14159 * self.r ** 2\n\n\nclass Rect:\n    def __init__(self, l, w):\n        self.l, self.w = l, w\n\n    def area(self):\n        return self.l * self.w\n\n\nclass Tri:\n    def __init__(self, b, h):\n        self.b, self.h = b, h\n\n    def area(self):\n        return self.b * self.h / 2\n\n\nk = {\"circle\": Circle, \"rect\": Rect, \"tri\": Tri}\nn = int(input())\nshapes = []\nfor _ in range(n):\n    p = input().split()\n    shapes.append(k[p[0]](*map(int, p[1:])))\nprint(f\"{sum(s.area() for s in shapes):.2f}\")", lambda r: cmd_block(r, r.randint(1, 5), lambda r: r.choice([f"circle {r.randint(1, 9)}", f"rect {r.randint(1, 9)} {r.randint(1, 9)}", f"tri {r.randint(1, 9)} {r.randint(1, 9)}"])), edges=["1\ncircle 1\n"])
py(O, "Duck Typing Quackers", "`Duck`, `Robot` and `Person` each have a `make_sound()` method but share no parent. A function `chorus(items)` calls it on every item. Print the sounds of a list of kinds, one per line (`Quack`, `Beep` and `Hello`).", "First line `n`, then `n` kinds.", "One sound per line.", "1 <= n <= 20",
   "class Duck:\n    def make_sound(self):\n        return \"Quack\"\n\n\nclass Robot:\n    def make_sound(self):\n        return \"Beep\"\n\n\nclass Person:\n    def make_sound(self):\n        return \"Hello\"\n\n\ndef chorus(items):\n    for i in items:\n        print(i.make_sound())\n\n\nk = {\"duck\": Duck, \"robot\": Robot, \"person\": Person}\nn = int(input())\nchorus(k[input().strip()]() for _ in range(n))", lambda r: cmd_block(r, r.randint(1, 6), lambda r: r.choice(["duck", "robot", "person"])), edges=["1\nrobot\n"])
py(O, "Discount Strategies", "A checkout applies a strategy object with `apply(price)`: `NoDiscount`, `Flat(50)` (never below zero) and `Percent(10)` (rounded down). Each line `strategy price` with strategy `none`, `flat` or `percent`; print the final price.", "First line `n`, then `n` lines.", "One price per line.", "1 <= n <= 20",
   "class NoDiscount:\n    def apply(self, p):\n        return p\n\n\nclass Flat:\n    def apply(self, p):\n        return max(0, p - 50)\n\n\nclass Percent:\n    def apply(self, p):\n        return p * 90 // 100\n\n\nk = {\"none\": NoDiscount, \"flat\": Flat, \"percent\": Percent}\nn = int(input())\nfor _ in range(n):\n    a, p = input().split()\n    print(k[a]().apply(int(p)))", lambda r: cmd_block(r, r.randint(1, 6), lambda r: f"{r.choice(['none', 'flat', 'percent'])} {r.randint(10, 900)}"), edges=["1\nflat 10\n"])
py(O, "Payment Processing List", "A store has `Cash`, `Card` and `Wallet` payment classes with `pay(amount)` returning the amount charged: cash charges the amount, card adds 2% (rounded up), wallet charges the amount minus 5 but never below 0. Print the total charged for a list of payments.", "First line `n`, then `n` lines `kind amount`.", "The total.", "1 <= n <= 20",
   "class Cash:\n    def pay(self, a):\n        return a\n\n\nclass Card:\n    def pay(self, a):\n        return a + (a * 2 + 99) // 100\n\n\nclass Wallet:\n    def pay(self, a):\n        return max(0, a - 5)\n\n\nk = {\"cash\": Cash, \"card\": Card, \"wallet\": Wallet}\nn = int(input())\ntotal = 0\nfor _ in range(n):\n    a, x = input().split()\n    total += k[a]().pay(int(x))\nprint(total)", lambda r: cmd_block(r, r.randint(1, 6), lambda r: f"{r.choice(['cash', 'card', 'wallet'])} {r.randint(1, 900)}"), edges=["1\nwallet 2\n"])
py(O, "Render Different Widgets", "`Button`, `Label` and `Input` widgets each have `render()` returning text: `[ <text> ]`, `<text>` and `<text>: ____`. Print the rendering of each widget line `kind text`.", "First line `n`, then `n` lines.", "One rendering per widget.", "1 <= n <= 20",
   "class Button:\n    def __init__(self, t):\n        self.t = t\n\n    def render(self):\n        return f\"[ {self.t} ]\"\n\n\nclass Label:\n    def __init__(self, t):\n        self.t = t\n\n    def render(self):\n        return self.t\n\n\nclass Input:\n    def __init__(self, t):\n        self.t = t\n\n    def render(self):\n        return f\"{self.t}: ____\"\n\n\nk = {\"button\": Button, \"label\": Label, \"input\": Input}\nn = int(input())\nfor _ in range(n):\n    a, t = input().split()\n    print(k[a](t).render())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(['button', 'label', 'input'])} {r.choice(['OK', 'Name', 'Email', 'Save'])}"), edges=["1\nlabel x\n"])
py(O, "Polymorphic Greeting by Language", "Classes `English`, `Hindi` and `Telugu` each have `greet(name)` returning `Hello <name>`, `Namaste <name>` and `Namaskaram <name>`. Each line `language name`; print the greeting.", "First line `n`, then `n` lines.", "One greeting per line.", "1 <= n <= 20",
   "class English:\n    def greet(self, n):\n        return f\"Hello {n}\"\n\n\nclass Hindi:\n    def greet(self, n):\n        return f\"Namaste {n}\"\n\n\nclass Telugu:\n    def greet(self, n):\n        return f\"Namaskaram {n}\"\n\n\nk = {\"english\": English, \"hindi\": Hindi, \"telugu\": Telugu}\nn = int(input())\nfor _ in range(n):\n    a, b = input().split()\n    print(k[a]().greet(b))", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(['english', 'hindi', 'telugu'])} {r.choice(NM)}"), edges=["1\nhindi A\n"])
py(O, "Salary Components Polymorphism", "Pay components `Basic`, `Bonus` and `Deduction` each have `amount()`. `Basic(x)` gives `x`, `Bonus(x)` gives `x` and `Deduction(x)` gives `-x`. Print the net of a list of components.", "First line `n`, then `n` lines `kind x`.", "The net amount.", "1 <= n <= 20",
   "class Basic:\n    def __init__(self, x):\n        self.x = x\n\n    def amount(self):\n        return self.x\n\n\nclass Bonus(Basic):\n    pass\n\n\nclass Deduction(Basic):\n    def amount(self):\n        return -self.x\n\n\nk = {\"basic\": Basic, \"bonus\": Bonus, \"deduction\": Deduction}\nn = int(input())\nparts = []\nfor _ in range(n):\n    a, x = input().split()\n    parts.append(k[a](int(x)))\nprint(sum(p.amount() for p in parts))", lambda r: cmd_block(r, r.randint(1, 6), lambda r: f"{r.choice(['basic', 'bonus', 'deduction'])} {r.randint(100, 9000)}"), edges=["1\ndeduction 5\n"])
py(O, "Operator Objects Calculator", "A calculator has `Add`, `Sub`, `Mul` classes with `apply(a, b)`. Each line `op a b`; print the result.", "First line `n`, then `n` lines.", "One result per line.", "1 <= n <= 20",
   "class Add:\n    def apply(self, a, b):\n        return a + b\n\n\nclass Sub:\n    def apply(self, a, b):\n        return a - b\n\n\nclass Mul:\n    def apply(self, a, b):\n        return a * b\n\n\nk = {\"add\": Add, \"sub\": Sub, \"mul\": Mul}\nn = int(input())\nfor _ in range(n):\n    o, a, b = input().split()\n    print(k[o]().apply(int(a), int(b)))", lambda r: cmd_block(r, r.randint(1, 6), lambda r: f"{r.choice(['add', 'sub', 'mul'])} {r.randint(-20, 20)} {r.randint(-20, 20)}"), edges=["1\nmul 0 5\n"])
py(O, "Sort Mixed Objects by Common Method", "`Car` and `Bike` objects both have `cost()`. Sort a mixed list by cost (ties by name) and print the names. `Car(price)` costs `price + 1000`; `Bike(price)` costs `price`.", "First line `n`, then `n` lines `kind name price`.", "The sorted names.", "1 <= n <= 20",
   "class Car:\n    def __init__(self, name, p):\n        self.name, self.p = name, p\n\n    def cost(self):\n        return self.p + 1000\n\n\nclass Bike:\n    def __init__(self, name, p):\n        self.name, self.p = name, p\n\n    def cost(self):\n        return self.p\n\n\nk = {\"car\": Car, \"bike\": Bike}\nn = int(input())\nv = []\nfor _ in range(n):\n    a, b, c = input().split()\n    v.append(k[a](b, int(c)))\nv.sort(key=lambda o: (o.cost(), o.name))\nprint(*(o.name for o in v))", lambda r: (lambda n: rows(n, *[f"{r.choice(['car', 'bike'])} {nm} {r.randint(1, 20) * 100}" for nm in r.sample(NM, n)]))(r.randint(2, 7)), edges=["1\nbike a 1\n"])

# ---- 15 class methods, static methods, class attributes and composition ----
py(O, "Create From String Classmethod", "A `Person` class has a `classmethod` `from_string(s)` that builds an object from text like `Asha-25`. Print `name is age years old` for each text.", "First line `n`, then `n` lines `name-age`.", "One sentence per line.", "1 <= n <= 20",
   "class Person:\n    def __init__(self, name, age):\n        self.name, self.age = name, age\n\n    @classmethod\n    def from_string(cls, s):\n        n, a = s.split(\"-\")\n        return cls(n, int(a))\n\n\nn = int(input())\nfor _ in range(n):\n    p = Person.from_string(input().strip())\n    print(f\"{p.name} is {p.age} years old\")", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(NM)}-{r.randint(5, 80)}"), edges=["1\nA-1\n"])
py(O, "Static Validator Methods", "A `Validator` class holds `@staticmethod`s `is_email(s)` (contains one `@` and a `.` after it) and `is_phone(s)` (exactly 10 digits). Each line `email x` or `phone x`; print `valid` or `invalid`.", "First line `n`, then `n` lines.", "One verdict per line.", "1 <= n <= 20",
   "class Validator:\n    @staticmethod\n    def is_email(s):\n        return s.count(\"@\") == 1 and \".\" in s.split(\"@\")[1]\n\n    @staticmethod\n    def is_phone(s):\n        return len(s) == 10 and s.isdigit()\n\n\nn = int(input())\nfor _ in range(n):\n    k, s = input().split()\n    ok = Validator.is_email(s) if k == \"email\" else Validator.is_phone(s)\n    print(\"valid\" if ok else \"invalid\")", lambda r: cmd_block(r, r.randint(2, 6), lambda r: r.choice([f"email {r.choice(['a@b.com', 'ab.com', 'a@b', 'x@y.in', 'a@@b.c'])}", f"phone {r.choice(['9876543210', '12345', '98765abcde', '0000000000'])}"])), edges=["1\nemail a@b.c\n"])
py(O, "Instance Counter Class Attribute", "A `Ticket` class counts the tickets issued in a class attribute `issued`. Process commands `issue` (print the new ticket number) and `count` (print how many were issued).", "First line `n`, then `n` commands.", "One line per command.", "1 <= n <= 30",
   "class Ticket:\n    issued = 0\n\n    def __init__(self):\n        Ticket.issued += 1\n        self.no = Ticket.issued\n\n\nn = int(input())\nfor _ in range(n):\n    if input().strip() == \"issue\":\n        print(Ticket().no)\n    else:\n        print(Ticket.issued)", lambda r: cmd_block(r, r.randint(3, 10), lambda r: r.choice(["issue", "issue", "count"])), edges=["1\ncount\n"])
py(O, "Class vs Instance Attribute", "A `Light` class has a class attribute `brightness = 5`. Commands: `all v` sets the class attribute, `mine v` sets the instance attribute on one fixed object `lamp`, and `show` prints `<class value> <lamp value>`.", "First line `n`, then `n` commands.", "One line per `show`.", "1 <= n <= 30",
   "class Light:\n    brightness = 5\n\n\nlamp = Light()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"all\":\n        Light.brightness = int(c[1])\n    elif c[0] == \"mine\":\n        lamp.brightness = int(c[1])\n    else:\n        print(Light.brightness, lamp.brightness)", lambda r: cmd_block(r, r.randint(3, 9), lambda r: r.choice([f"all {r.randint(1, 9)}", f"mine {r.randint(1, 9)}", "show"])), edges=["1\nshow\n"])
py(O, "Alternative Constructor for Dates", "A `Date` class has a classmethod `from_days(n)` that turns a day count into `years months days` assuming 12 months of 30 days and 360-day years. Print the three numbers for each count.", "First line `n`, then `n` day counts.", "One line per count.", "0 <= days <= 10^5",
   "class Date:\n    def __init__(self, y, m, d):\n        self.y, self.m, self.d = y, m, d\n\n    @classmethod\n    def from_days(cls, n):\n        return cls(n // 360, n % 360 // 30, n % 30)\n\n\nn = int(input())\nfor x in map(int, input().split()):\n    d = Date.from_days(x)\n    print(d.y, d.m, d.d)", lambda r: (lambda k: rows(k, " ".join(str(r.randint(0, 5000)) for _ in range(k))))(r.randint(1, 5)), edges=["1\n0\n"])
py(O, "Temperature Static Converter", "A `Convert` class offers static methods `c_to_f(c)` and `f_to_c(f)`. Each line `c x` or `f x`; print the converted value with one decimal.", "First line `n`, then `n` lines.", "One value per line.", "1 <= n <= 20",
   "class Convert:\n    @staticmethod\n    def c_to_f(c):\n        return c * 9 / 5 + 32\n\n    @staticmethod\n    def f_to_c(f):\n        return (f - 32) * 5 / 9\n\n\nn = int(input())\nfor _ in range(n):\n    k, x = input().split()\n    x = float(x)\n    print(f\"{Convert.c_to_f(x) if k == 'c' else Convert.f_to_c(x):.1f}\")", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice('cf')} {r.randint(-40, 120)}"), edges=["1\nc 0\n"])
py(O, "Singleton Configuration", "A `Config` class always returns the same object (a singleton) through `__new__`. Process `n` commands `set value` and `get`: all objects share the value. Create a fresh `Config()` for every command and print `get` results (or `unset`).", "First line `n`, then `n` commands.", "One line per `get`.", "1 <= n <= 30",
   "class Config:\n    _inst = None\n\n    def __new__(cls):\n        if cls._inst is None:\n            cls._inst = super().__new__(cls)\n            cls._inst.value = \"unset\"\n        return cls._inst\n\n\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    cfg = Config()\n    if c[0] == \"set\":\n        cfg.value = c[1]\n    else:\n        print(cfg.value)", lambda r: cmd_block(r, r.randint(3, 8), lambda r: r.choice([f"set {r.choice(['dark', 'light', 'blue'])}", "get"])), edges=["1\nget\n"])
py(O, "Library Has Books", "A `Library` object is composed of `Book` objects. Commands: `add title pages`, `total` (total pages) and `longest` (title of the longest book, first if tied, or `none`).", "First line `n`, then `n` commands.", "One line per `total` and `longest`.", "1 <= n <= 30",
   "class Book:\n    def __init__(self, t, p):\n        self.t, self.p = t, p\n\n\nclass Library:\n    def __init__(self):\n        self.books = []\n\n    def add(self, t, p):\n        self.books.append(Book(t, p))\n\n    def total(self):\n        return sum(b.p for b in self.books)\n\n    def longest(self):\n        return max(self.books, key=lambda b: b.p).t if self.books else \"none\"\n\n\nlib = Library()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"add\":\n        lib.add(c[1], int(c[2]))\n    elif c[0] == \"total\":\n        print(lib.total())\n    else:\n        print(lib.longest())", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"add {r.choice(['dune', 'emma', 'iliad', 'ulysses'])} {r.randint(100, 900)}", "total", "longest"])), edges=["1\nlongest\n"])
py(O, "Order Made of Items", "An `Order` holds `Item` objects. `add name price qty` adds an item; `bill` prints the total; `items` prints the number of different item names. Process the commands.", "First line `n`, then `n` commands.", "One line per `bill` and `items`.", "1 <= n <= 30",
   "class Item:\n    def __init__(self, name, price, qty):\n        self.name, self.price, self.qty = name, price, qty\n\n    def line(self):\n        return self.price * self.qty\n\n\nclass Order:\n    def __init__(self):\n        self.items = []\n\n    def add(self, *a):\n        self.items.append(Item(*a))\n\n    def bill(self):\n        return sum(i.line() for i in self.items)\n\n\no = Order()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"add\":\n        o.add(c[1], int(c[2]), int(c[3]))\n    elif c[0] == \"bill\":\n        print(o.bill())\n    else:\n        print(len({i.name for i in o.items}))", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"add {r.choice(['pen', 'ink', 'bag'])} {r.randint(5, 90)} {r.randint(1, 5)}", "bill", "items"])), edges=["1\nbill\n"])
py(O, "Team and Players", "A `Team` contains `Player` objects. `join name score` adds a player; `best` prints the best player's name (first if tied, `none` if empty); `avg` prints the average score with one decimal (`0.0` if empty).", "First line `n`, then `n` commands.", "One line per `best` and `avg`.", "1 <= n <= 30",
   "class Player:\n    def __init__(self, name, score):\n        self.name, self.score = name, score\n\n\nclass Team:\n    def __init__(self):\n        self.players = []\n\n    def join(self, n, s):\n        self.players.append(Player(n, s))\n\n    def best(self):\n        return max(self.players, key=lambda p: p.score).name if self.players else \"none\"\n\n    def avg(self):\n        return sum(p.score for p in self.players) / len(self.players) if self.players else 0.0\n\n\nt = Team()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"join\":\n        t.join(c[1], int(c[2]))\n    elif c[0] == \"best\":\n        print(t.best())\n    else:\n        print(f\"{t.avg():.1f}\")", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"join {r.choice(NM)} {r.randint(0, 100)}", "best", "avg"])), edges=["2\nbest\navg\n"])
py(O, "Car With Engine Part", "A `Car` has an `Engine` part. `Engine.start()` uses 1 litre and returns whether the tank had fuel; the `Car` has `drive(km)` which uses `km // 10` litres if enough fuel is present (else it says `Out of fuel` and keeps the fuel). Commands: `fuel x`, `drive km`. Print the result of each `drive` (`Driven` or `Out of fuel`) and the fuel left after it.", "First line `n`, then `n` commands.", "One line per `drive`.", "1 <= n <= 30",
   "class Engine:\n    def __init__(self):\n        self.fuel = 0\n\n    def use(self, litres):\n        if litres > self.fuel:\n            return False\n        self.fuel -= litres\n        return True\n\n\nclass Car:\n    def __init__(self):\n        self.engine = Engine()\n\n    def drive(self, km):\n        return \"Driven\" if self.engine.use(km // 10) else \"Out of fuel\"\n\n\ncar = Car()\nn = int(input())\nfor _ in range(n):\n    c, x = input().split()\n    if c == \"fuel\":\n        car.engine.fuel += int(x)\n    else:\n        print(car.drive(int(x)), car.engine.fuel)", lambda r: cmd_block(r, r.randint(3, 9), lambda r: r.choice([f"fuel {r.randint(1, 20)}", f"drive {r.randint(10, 200)}"])), edges=["1\ndrive 10\n"])
py(O, "Shopping Cart Composition", "A `Cart` holds `Product` objects with a price. `add name price`, `remove name` (removes the first product with that name, ignoring missing ones), and `total` (print the sum). Process the commands.", "First line `n`, then `n` commands.", "One line per `total`.", "1 <= n <= 30",
   "class Product:\n    def __init__(self, name, price):\n        self.name, self.price = name, price\n\n\nclass Cart:\n    def __init__(self):\n        self.items = []\n\n    def add(self, n, p):\n        self.items.append(Product(n, p))\n\n    def remove(self, n):\n        for i, p in enumerate(self.items):\n            if p.name == n:\n                del self.items[i]\n                return\n\n    def total(self):\n        return sum(p.price for p in self.items)\n\n\nc = Cart()\nn = int(input())\nfor _ in range(n):\n    x = input().split()\n    if x[0] == \"add\":\n        c.add(x[1], int(x[2]))\n    elif x[0] == \"remove\":\n        c.remove(x[1])\n    else:\n        print(c.total())", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"add {r.choice(['pen', 'ink', 'bag'])} {r.randint(5, 90)}", f"remove {r.choice(['pen', 'ink', 'bag'])}", "total"])), edges=["1\ntotal\n"])
py(O, "Class Registry With Decorator", "A `Registry` class keeps a dictionary of handlers; `Registry.register(name)` is a decorator that stores a function. Handlers `double` and `negate` are registered. Each line `name x`; print the handler's result or `unknown`.", "First line `n`, then `n` lines `name x`.", "One result per line.", "1 <= n <= 20",
   "class Registry:\n    handlers = {}\n\n    @classmethod\n    def register(cls, name):\n        def deco(fn):\n            cls.handlers[name] = fn\n            return fn\n\n        return deco\n\n\n@Registry.register(\"double\")\ndef double(x):\n    return x * 2\n\n\n@Registry.register(\"negate\")\ndef negate(x):\n    return -x\n\n\nn = int(input())\nfor _ in range(n):\n    a, x = input().split()\n    f = Registry.handlers.get(a)\n    print(f(int(x)) if f else \"unknown\")", lambda r: cmd_block(r, r.randint(1, 6), lambda r: f"{r.choice(['double', 'negate', 'square'])} {r.randint(-9, 20)}"), edges=["1\nsquare 1\n"])
py(O, "Parking Lot Objects", "A `ParkingLot` with `cap` slots holds `Car` objects. `park plate` parks a car if there is room (`Parked` or `Full`); `leave plate` removes it (`Left` or `Not here`); `free` prints the free slots. Print each response.", "First line `cap n`, then `n` commands.", "One line per command.", "1 <= cap <= 10, 1 <= n <= 30",
   "class Car:\n    def __init__(self, plate):\n        self.plate = plate\n\n\nclass ParkingLot:\n    def __init__(self, cap):\n        self.cap = cap\n        self.cars = []\n\n    def park(self, plate):\n        if len(self.cars) >= self.cap:\n            return \"Full\"\n        self.cars.append(Car(plate))\n        return \"Parked\"\n\n    def leave(self, plate):\n        for c in self.cars:\n            if c.plate == plate:\n                self.cars.remove(c)\n                return \"Left\"\n        return \"Not here\"\n\n    def free(self):\n        return self.cap - len(self.cars)\n\n\ncap, n = map(int, input().split())\nlot = ParkingLot(cap)\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"park\":\n        print(lot.park(c[1]))\n    elif c[0] == \"leave\":\n        print(lot.leave(c[1]))\n    else:\n        print(lot.free())", lambda r: (lambda n: rows(f"{r.randint(1, 3)} {n}", *[r.choice([f"park {r.choice(['AP1', 'TS2', 'KA3', 'MH4'])}", f"leave {r.choice(['AP1', 'TS2', 'KA3', 'MH4'])}", "free"]) for _ in range(n)]))(r.randint(4, 10)), edges=["1 1\nfree\n"])
py(O, "Employee Directory Class", "An `EmployeeDirectory` keeps `Employee` objects by id. `add id name dept`, `find id` (prints `name (dept)` or `not found`) and `count dept` (prints how many employees are in the department). Process the commands.", "First line `n`, then `n` commands.", "One line per `find` and `count`.", "1 <= n <= 30",
   "class Employee:\n    def __init__(self, i, name, dept):\n        self.i, self.name, self.dept = i, name, dept\n\n\nclass EmployeeDirectory:\n    def __init__(self):\n        self.by_id = {}\n\n    def add(self, i, name, dept):\n        self.by_id[i] = Employee(i, name, dept)\n\n    def find(self, i):\n        e = self.by_id.get(i)\n        return f\"{e.name} ({e.dept})\" if e else \"not found\"\n\n    def count(self, dept):\n        return sum(1 for e in self.by_id.values() if e.dept == dept)\n\n\nd = EmployeeDirectory()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"add\":\n        d.add(c[1], c[2], c[3])\n    elif c[0] == \"find\":\n        print(d.find(c[1]))\n    else:\n        print(d.count(c[1]))", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"add {r.randint(1, 5)} {r.choice(NM)} {r.choice(['HR', 'IT'])}", f"find {r.randint(1, 5)}", f"count {r.choice(['HR', 'IT'])}"])), edges=["1\nfind 1\n"])
